import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3]
    let ys = xs.iterator().map(|x| x * 10).take(2).collect()
    for y in ys { io.println("mt ${y}") }

    let a = xs.iterator().skip(2).collect()
    for v in a { io.println("sk ${v}") }

    let b = xs.iterator().filter(|x| x > 2).count()
    io.println("cnt ${b}")

    let c = xs.iterator().map(|x| x * 2).skip(1).take(2).collect()
    for v in c { io.println("ch ${v}") }

    let fs = [1.5, 2.5, 3.5]
    let d = fs.iterator().map(|x| x + 1.0).collect()
    for v in d { io.println("f ${v}") }

    let e = xs.iterator().map(|x| x * 10).take(0).collect()
    let n = e.iterator().count()
    io.println("zero ${n}")

    return Ok(())
}
